def split_csv(line):
    fields = []
    i = 0

    while i < len(line):
        # Parse one field
        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - add one quote to field
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: comma or end of line
                        if i < len(line) and line[i] != ',':
                            return None
                        if i < len(line):
                            i += 1  # Skip the comma
                        fields.append(''.join(field))
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Loop ended without finding closing quote
                return None
        else:
            # Unquoted field
            field = []
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote not allowed in unquoted field
                    return None
                field.append(line[i])
                i += 1

            fields.append(''.join(field))
            if i < len(line):
                i += 1  # Skip the comma

    return fields

